/**
 * Shared synthetic dataset for the Logistic Regression chapter.
 *
 * Two clouds of 2D points — class 0 (blue) and class 1 (red) — drawn so that
 * the optimal linear boundary tilts gently from lower-left to upper-right.
 * Generated by hand so the data is deterministic across reloads and the same
 * dragging exercise works on every machine.
 *
 * For the multiclass act we add a third cloud at the top.
 *
 * Coordinate frame: x in 0..40, y in 0..40 — same conventions as the linear
 * regression chapter so the visual family reads as one.
 */
export interface Pt {
  x: number
  y: number
}

export interface LabeledPt extends Pt {
  /** 0 = blue (negative class), 1 = red (positive class) */
  y_label: 0 | 1
}

