/* ---- SVG layout primitives shared by every 2D pane in this chapter. ---- */

export const VIEW_W = 600
export const VIEW_H = 480

/** Data range. x in 0..40, y in 0..40. */
export const X_MIN = 0
export const X_MAX = 40
export const Y_MIN = 0
export const Y_MAX = 40

const PAD_L = 64
const PAD_R = 32
const PAD_T = 40
const PAD_B = 56

export const PLOT_X0 = PAD_L
export const PLOT_X1 = VIEW_W - PAD_R
export const PLOT_Y0 = PAD_T
export const PLOT_Y1 = VIEW_H - PAD_B
export const PLOT_W = PLOT_X1 - PLOT_X0
export const PLOT_H = PLOT_Y1 - PLOT_Y0

export const dataToSvgX = (x: number) =>
  PLOT_X0 + ((x - X_MIN) / (X_MAX - X_MIN)) * PLOT_W
export const dataToSvgY = (y: number) =>
  PLOT_Y1 - ((y - Y_MIN) / (Y_MAX - Y_MIN)) * PLOT_H

/* ---- The logistic function and its friends. ---- */

/** σ(z) = 1 / (1 + e^(-z)) — clamped for numerical safety. */
export function sigmoid(z: number): number {
  if (z >= 0) {
    const ez = Math.exp(-z)
    return 1 / (1 + ez)
  } else {
    const ez = Math.exp(z)
    return ez / (1 + ez)
  }
}

/**
 * A linear decision rule parametrised as a line in the feature space.
 *
 *   z(x, y) = w_x · x + w_y · y + b
 *
 * The decision boundary is z = 0, i.e. p = σ(z) = 0.5.
 * `gain` (a positive scalar) scales the linear combination, controlling how
 * steeply σ transitions from 0 to 1 across the boundary. This is what the
 * sigmoid-steepness slider in act 3 controls.
 */
export interface BoundaryState {
  /** angle of the boundary line, in radians. 0 = vertical (boundary along y-axis). */
  angle: number
  /** signed perpendicular offset from the plot centre, in data units. */
  offset: number
  /** scalar multiplier on z. Higher = sharper transition. */
  gain: number
  interacting: boolean
}

export const INITIAL_BOUNDARY: BoundaryState = {
  angle: -0.55,
  offset: 0,
  gain: 0.4,
  interacting: false,
}

const CENTER_X = (X_MIN + X_MAX) / 2
const CENTER_Y = (Y_MIN + Y_MAX) / 2

/** Unit normal pointing toward the positive class side. */
export function boundaryNormal(s: { angle: number }): { nx: number; ny: number } {
  // The boundary line direction is (cos(angle), sin(angle)).
  // The normal (perpendicular) is (-sin, cos).
  return { nx: -Math.sin(s.angle), ny: Math.cos(s.angle) }
}

/** Signed linear score z for a point. */
export function score(s: BoundaryState, p: Pt): number {
  const { nx, ny } = boundaryNormal(s)
  // signed distance from boundary line, in data units
  const d = nx * (p.x - CENTER_X) + ny * (p.y - CENTER_Y) - s.offset
  return s.gain * d
}

/** σ(z(p)) — predicted probability that p belongs to class 1. */
export function predict(s: BoundaryState, p: Pt): number {
  return sigmoid(score(s, p))
}

/** Endpoints of the boundary line clipped to the plot rectangle in data units. */
export function boundaryEndpoints(
  s: BoundaryState,
): { x1: number; y1: number; x2: number; y2: number } {
  // Parametric form: line = anchor + t · direction
  // anchor = centre + offset · normal
  const { nx, ny } = boundaryNormal(s)
  const ax = CENTER_X + s.offset * nx
  const ay = CENTER_Y + s.offset * ny
  const dx = Math.cos(s.angle)
  const dy = Math.sin(s.angle)
  // Clip to a generous range — the renderer clips further.
  const T = 80
  return {
    x1: ax - T * dx,
    y1: ay - T * dy,
    x2: ax + T * dx,
    y2: ay + T * dy,
  }
}

/* ---- Loss functions. ---- */

/** Binary log loss (mean over the dataset). */
export function logLoss(s: BoundaryState, pts: LabeledPt[] = POINTS): number {
  let total = 0
  const EPS = 1e-7
  for (const p of pts) {
    const phat = Math.max(EPS, Math.min(1 - EPS, predict(s, p)))
    total += -(p.y_label * Math.log(phat) + (1 - p.y_label) * Math.log(1 - phat))
  }
  return total / pts.length
}

/** Mean squared error on the probability output — for comparison in act 4. */
export function mseLoss(s: BoundaryState, pts: LabeledPt[] = POINTS): number {
  let total = 0
  for (const p of pts) {
    const phat = predict(s, p)
    const r = p.y_label - phat
    total += r * r
  }
  return total / pts.length
}

/* ---- Gradient descent step (act 5). ---- */

/**
 * Compute analytic gradient of the mean log loss with respect to (w_x, w_y, b),
 * where the boundary state is reparametrised on the fly via the (angle, offset,
 * gain) triple. For act 5 we keep `gain` fixed and let GD update (w_x, w_y, b)
 * directly, then re-derive (angle, offset).
 *
 * Returns the new (w_x, w_y, b) tuple after one step at the given learning rate.
 */
export interface LinearWeights {
  wx: number
  wy: number
  b: number
}

/** Convert boundary state to (wx, wy, b). z = wx·x + wy·y + b. */
export function toWeights(s: BoundaryState): LinearWeights {
  const { nx, ny } = boundaryNormal(s)
  // z = gain · (nx·(x − cx) + ny·(y − cy) − offset)
  //   = gain·nx · x + gain·ny · y + gain·(−nx·cx − ny·cy − offset)
  const wx = s.gain * nx
  const wy = s.gain * ny
  const b = s.gain * (-nx * CENTER_X - ny * CENTER_Y - s.offset)
  return { wx, wy, b }
}

/** Convert (wx, wy, b) back to boundary state, preserving an existing gain. */
export function fromWeights(w: LinearWeights, prevGain: number): BoundaryState {
  const mag = Math.sqrt(w.wx * w.wx + w.wy * w.wy)
  const gain = mag > 1e-8 ? mag : prevGain
  const nx = mag > 1e-8 ? w.wx / mag : 1
  const ny = mag > 1e-8 ? w.wy / mag : 0
  // From normal (nx, ny) recover angle of the boundary direction:
  //   normal = (-sin a, cos a)  =>  a = atan2(nx, -ny) ... but with a sign care:
  //   sin a = -nx, cos a = ny  =>  a = atan2(-nx, ny)
  const angle = Math.atan2(-nx, ny)
  // b = gain·(−nx·cx − ny·cy − offset)
  //   => offset = −nx·cx − ny·cy − b/gain
  const offset = -nx * CENTER_X - ny * CENTER_Y - w.b / gain
  return { angle, offset, gain, interacting: false }
}

/** One gradient-descent step. */
export function gradStep(
  s: BoundaryState,
  lr: number,
  pts: LabeledPt[] = POINTS,
): BoundaryState {
  const w = toWeights(s)
  let gwx = 0
  let gwy = 0
  let gb = 0
  for (const p of pts) {
    const z = w.wx * p.x + w.wy * p.y + w.b
    const phat = sigmoid(z)
    const err = phat - p.y_label
    gwx += err * p.x
    gwy += err * p.y
    gb += err
  }
  const N = pts.length
  gwx /= N
  gwy /= N
  gb /= N
  const next: LinearWeights = {
    wx: w.wx - lr * gwx,
    wy: w.wy - lr * gwy,
    b: w.b - lr * gb,
  }
  return fromWeights(next, s.gain)
}

/* ---- Multiclass (softmax). ---- */

/**
 * NOTE: MulticlassState + INITIAL_MULTICLASS live in Multiclass.tsx so each
 * playable owns its state shape. We keep the helpers (weights, softmax, class
 * colours) here so they can be shared.
 */

/**
 * Pre-computed one-vs-rest linear scores for the MULTI_POINTS dataset.
 *
 * Hand-tuned (not learned at runtime) so the three boundaries draw nice
 * separating lines across the three clouds. Each row is (wx, wy, b) for
 * the corresponding class's linear scorer.
 */
export const MULTI_WEIGHTS: LinearWeights[] = [
  // Class 0 (blue, lower-left) — favoured when x small AND y small
  { wx: -0.45, wy: -0.35, b: 9.0 },
  // Class 1 (red, lower-right) — favoured when x large AND y small
  { wx: 0.45, wy: -0.35, b: -9.0 },
  // Class 2 (amber, upper-center) — favoured when y large
  { wx: 0.0, wy: 0.55, b: -17.0 },
]

/** Softmax over the three class scores at a point. */
export function softmaxScores(p: Pt): [number, number, number] {
  const zs = MULTI_WEIGHTS.map((w) => w.wx * p.x + w.wy * p.y + w.b)
  const m = Math.max(...zs)
  const ex = zs.map((z) => Math.exp(z - m))
  const sum = ex.reduce((a, b) => a + b, 0)
  return [ex[0] / sum, ex[1] / sum, ex[2] / sum]
}

